morse.watch(".status-bar", bar => {
  const WORK = 25 * 60, BREAK = 5 * 60;
  let mode = "work", left = WORK, timer = null;
  const fmt = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
  const item = morse.el("div", { class: "status-bar-item pomodoro-item mod-clickable", "aria-label": "Click: start/pause. Double-click: reset", "data-tooltip-position": "top" });
  const render = () => {
    item.textContent = (mode === "work" ? "🍅 " : "☕ ") + fmt(left);
    item.classList.toggle("running", !!timer && mode === "work");
    item.classList.toggle("break", !!timer && mode === "break");
  };
  const stop = () => { if (timer) { clearInterval(timer); timer = null; } };
  const tick = () => {
    left--;
    if (left <= 0) {
      mode = mode === "work" ? "break" : "work";
      left = mode === "work" ? WORK : BREAK;
      morse.toast(mode === "break" ? "Time for a break!" : "Back to work!");
    }
    render();
  };
  item.addEventListener("click", () => {
    if (timer) stop(); else timer = setInterval(tick, 1000);
    render();
  });
  item.addEventListener("dblclick", () => { stop(); mode = "work"; left = WORK; render(); });
  render();
  bar.prepend(item);
  return () => { stop(); item.remove(); };
});

