results.js:
const WORK = 25 * 60, BREAK = 5 * 60;
const saved = morse.store.get("pomo") || {};
let mode = saved.mode || "work";
let left = saved.left ?? WORK;
let running = false;
let timer = null;

const fmt = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
const save = () => morse.store.set("pomo", { mode, left });

function render() {
  morse.$$(".status-bar .plugin-pomodoro").forEach(el => {
    el.querySelector(".pomo-text").textContent = (mode === "work" ? "Focus " : "Break ") + fmt(left);
    el.classList.toggle("is-running", running);
    el.classList.toggle("is-break", mode === "break");
    el.setAttribute("aria-label", (running ? "Pause" : "Start") + " timer (double-click to reset, right-click to skip)");
  });
}

function tick() {
  left--;
  if (left <= 0) {
    morse.toast(mode === "work" ? "Focus session done. Take a break!" : "Break over. Back to focus!");
    mode = mode === "work" ? "break" : "work";
    left = mode === "work" ? WORK : BREAK;
  }
  save(); render();
}

function toggle() {
  running = !running;
  if (running) timer = setInterval(tick, 1000);
  else { clearInterval(timer); timer = null; }
  render();
}

function reset() {
  running = false; clearInterval(timer); timer = null;
  mode = "work"; left = WORK; save(); render();
}

function skip() {
  mode = mode === "work" ? "break" : "work";
  left = mode === "work" ? WORK : BREAK;
  save(); render();
}

