  const btn = morse.el('button', {
    class: 'button toolbar-button copy-title-btn',
    title: 'Copy note title',
    'aria-label': 'Copy note title',
    type: 'button',
    on: {
      click: async () => {
        try {
          await navigator.clipboard.writeText(input.value);
          icon.className = 'toolbar-icon fas fa-check';
          setTimeout(() => { icon.className = 'toolbar-icon fas fa-copy'; }, 1200);
        } catch (e) {
          morse.toast('Could not copy title');
