morse.watch('#workbench\\.parts\\.statusbar .left-items', left => {
  const WORK = 25 * 60, BREAK = 5 * 60;
  let mode = 'work', left_s = WORK, running = false;
  const fmt = s => String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');

  const icon = morse.el('span', { class: 'codicon codicon-play' });
  const label = morse.el('span', { text: fmt(left_s) });
  const a = morse.el('a', {
    class: 'statusbar-item-label', role: 'button', tabindex: '-1',
    'aria-label': 'Pomodoro timer: click to start or pause, double-click to reset'
  }, icon, label);
  const item = morse.el('div', {
    class: 'statusbar-item left has-command', id: 'morse-pomo', title: 'Pomodoro: click to start/pause, double-click to reset'
  }, a);

  const render = () => {
    label.textContent = (mode === 'break' ? 'Break ' : '') + fmt(left_s);
    icon.className = 'codicon ' + (running ? 'codicon-debug-pause' : 'codicon-play');
    item.classList.toggle('running', running);
    item.classList.toggle('break', mode === 'break');
  };

  morse.on(a, 'click', () => { running = !running; render(); });
  morse.on(a, 'dblclick', () => {
    running = false; mode = 'work'; left_s = WORK; render();
  });

  morse.every(1000, () => {
    if (!running) return;
    left_s--;
    if (left_s <= 0) {
      if (mode === 'work') { mode = 'break'; left_s = BREAK; morse.toast('Focus session done. Take a 5 minute break.'); }
      else { mode = 'work'; left_s = WORK; running = false; morse.toast('Break over. Ready for the next session.'); }
    }
    render();
  });

  left.appendChild(item);
  render();
});

