const KEY = "pomo";
const LEN = { work: 1500, break: 300 };
let st = morse.store.get(KEY) || { mode: "work", left: LEN.work, end: 0 };
const save = () => morse.store.set(KEY, st);
const fmt = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");

function render() {
  const item = document.getElementById("pomo-item");
  if (!item) return;
  item.classList.toggle("pomo-break", st.mode === "break");
  item.querySelector(".pomo-text").textContent = fmt(st.left);
  item.querySelector(".codicon").className = "codicon " + (st.end ? "codicon-debug-pause" : st.mode === "break" ? "codicon-coffee" : "codicon-play");
  const lab = (st.mode === "break" ? "Break" : "Focus") + " " + fmt(st.left) + (st.end ? " (click to pause)" : " (click to start)");
  item.setAttribute("aria-label", lab);
  item.firstChild.setAttribute("aria-label", lab);
  item.title = lab;
}

function toggle() {
  if (st.end) { st.left = Math.max(0, Math.round((st.end - Date.now()) / 1000)); st.end = 0; }
  else st.end = Date.now() + st.left * 1000;
  save(); render();
}
function reset() { st = { mode: "work", left: LEN.work, end: 0 }; save(); render(); }

function activate(fn) {
  return { click: fn, keydown: e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); fn(); } } };
}

morse.every(500, () => {
  if (st.end) {
    st.left = Math.max(0, Math.round((st.end - Date.now()) / 1000));
    if (st.left === 0) {
      const wasWork = st.mode === "work";
      st.mode = wasWork ? "break" : "work";
      st.left = LEN[st.mode];
      st.end = 0;
      save();
      morse.toast(wasWork ? "Focus session done. Take a 5 minute break." : "Break over. Ready to focus?");
    }
  }
  render();
});

