    morse.el("a", { class: "statusbar-item-label", role: "button", tabindex: "0", on: activate(toggle) },
      morse.el("span", { class: "codicon codicon-play" }),
      morse.el("span", { class: "pomo-text", text: fmt(st.left) })));
  const rst = morse.el("div", { class: "statusbar-item left has-command", id: "pomo-reset", title: "Reset Pomodoro" },
    morse.el("a", { class: "statusbar-item-label", role: "button", tabindex: "0", "aria-label": "Reset Pomodoro", on: activate(reset) },
