morse.watch(".status-bar", bar => {
  const WORK = 25 * 60, BREAK = 5 * 60;
  const saved = morse.store.get("pomo") || {};
  let mode = saved.mode || "work";
  let left = saved.left ?? WORK;
  let running = false;
  let last = 0;

  const label = morse.el("span", { text: "" });
  const item = morse.el("div", {
    class: "status-bar-item plugin-pomodoro mod-clickable",
    role: "button",
    tabindex: "0",
    "aria-label": "Pomodoro: click to start/pause, double-click to reset",
    "data-tooltip-position": "top"
  }, label);

  const fmt = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
  const render = () => {
    label.textContent = (mode === "work" ? "Focus " : "Break ") + fmt(left);
    item.classList.toggle("is-running", running);
    item.classList.toggle("is-break", mode === "break");
    morse.store.set("pomo", { mode, left });
  };

  const toggle = () => {
    running = !running;
    last = Date.now();
    render();
  };
  const reset = () => {
    running = false;
    mode = "work";
    left = WORK;
    render();
  };

  morse.on(item, "click", e => { if (e.detail < 2) toggle(); });
  morse.on(item, "dblclick", reset);
  morse.on(item, "keydown", e => {
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggle(); }
  });

  morse.every(1000, () => {
    if (!running) return;
    const now = Date.now();
    const d = Math.max(1, Math.round((now - last) / 1000));
    last = now;
    left -= d;
    if (left <= 0) {
      const wasWork = mode === "work";
      mode = wasWork ? "break" : "work";
      left = wasWork ? BREAK : WORK;
      morse.toast(wasWork ? "Focus session done. Take a break!" : "Break over. Back to focus!");
    }
    render();
  });

  bar.prepend(item);
  render();
});

