morse.watch(".status-bar", bar => {
  if (bar.querySelector(".plugin-pomodoro")) return;
  const WORK = 25 * 60, BREAK = 5 * 60;
  const saved = morse.store.get("pomo") || {};
  let mode = saved.mode || "work";
  let left = saved.left || WORK;
  let running = false;

  const svgNS = "http://www.w3.org/2000/svg";
  const icon = (paths) => {
    const s = document.createElementNS(svgNS, "svg");
    s.setAttribute("viewBox", "0 0 24 24");
    s.setAttribute("fill", "none");
    s.setAttribute("stroke", "currentColor");
    s.setAttribute("stroke-width", "2");
    s.setAttribute("stroke-linecap", "round");
    s.setAttribute("stroke-linejoin", "round");
    s.setAttribute("class", "svg-icon");
    s.innerHTML = paths;
    return s;
  };
  const PLAY = '<polygon points="6 3 20 12 6 21 6 3"/>';
  const PAUSE = '<rect x="14" y="4" width="4" height="16" rx="1"/><rect x="6" y="4" width="4" height="16" rx="1"/>';

  const iconWrap = morse.el("span", { class: "status-bar-item-icon" });
  const label = morse.el("span", { class: "status-bar-item-segment" });
  const item = morse.el("div", {
    class: "status-bar-item plugin-pomodoro mod-clickable",
    role: "button",
    tabindex: "0",
    "aria-label": "Pomodoro: click to start/pause, right-click to reset",
    "data-tooltip-position": "top"
  }, iconWrap, label);

  const fmt = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
  const render = () => {
    iconWrap.replaceChildren(icon(running ? PAUSE : PLAY));
    label.textContent = (mode === "work" ? "Focus " : "Break ") + fmt(left);
    item.classList.toggle("is-running", running);
    item.classList.toggle("is-break", mode === "break");
    morse.store.set("pomo", { mode, left });
  };
  const toggle = () => { running = !running; render(); };
  const reset = e => {
    e && e.preventDefault();
    running = false; mode = "work"; left = WORK; render();
  };

  morse.on(item, "click", toggle);
  morse.on(item, "contextmenu", reset);
  morse.on(item, "keydown", e => {
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggle(); }
  });

  morse.every(1000, () => {
    if (!running) return;
    left--;
    if (left <= 0) {
      mode = mode === "work" ? "break" : "work";
      left = mode === "work" ? WORK : BREAK;
      morse.toast(mode === "break" ? "Focus done. Time for a break!" : "Break over. Back to focus!");
    }
    render();
  });

  render();
  bar.prepend(item);
});

morse.watch(".status-bar .plugin-word-count", el => {
  const make = () => {
    let item = el.parentElement.querySelector(".plugin-read-time");
    if (!item) {
      item = morse.el("div", { class: "status-bar-item plugin-read-time" });
      el.after(item);
    }
    const seg = el.querySelector(".status-bar-item-segment");
    const words = seg ? parseInt(seg.textContent.replace(/[^\d]/g, ""), 10) || 0 : 0;
    const mins = Math.max(1, Math.ceil(words / 200));
    item.textContent = words ? mins + " min read" : "";
    item.style.display = words ? "" : "none";
  };
  make();
  const mo = new MutationObserver(make);
  mo.observe(el, { childList: true, subtree: true, characterData: true });
  return () => {
    mo.disconnect();
    const i = el.parentElement && el.parentElement.querySelector(".plugin-read-time");
    if (i) i.remove();
  };
});

morse.watch(".status-bar .plugin-word-count", el => {
  let item = el._readTime;
  if (!item || !item.isConnected) {
    item = morse.el("div", { class: "status-bar-item plugin-read-time", "aria-label": "Estimated reading time (200 words/min)", "data-tooltip-position": "top" });
    el._readTime = item;
    el.after(item);
  }
  const seg = el.querySelector(".status-bar-item-segment");
  const words = seg ? parseInt(seg.textContent.replace(/[^\d]/g, ""), 10) : NaN;
  let text = "";
  if (!isNaN(words)) {
    const mins = Math.ceil(words / 200);
    text = words === 0 ? "" : (words < 200 ? "< 1 min read" : mins + " min read");
  }
  if (item.textContent !== text) item.textContent = text;
  item.style.display = text && el.style.display !== "none" ? "" : "none";
}, { live: true });

