morse.every(500, () => {
  const cm = document.querySelector(".cm-content");
  let text = "";
  if (cm) {
    const v = cm.cmView && (cm.cmView.view || (cm.cmView.root && cm.cmView.root.view));
    text = v && v.state ? v.state.doc.toString() : cm.innerText;
  }
  const n = text.trim() ? text.trim().split(/\s+/).length : 0;
  morse.$$(".word-count-label").forEach(s => {
    const t = n + (n === 1 ? " word" : " words");
    if (s.textContent !== t) s.textContent = t;
  });
});

function getText() {
  const c = document.querySelector('.cm-content');
  if (!c) return null;
  try {
    const v = (c.cmView && (c.cmView.view || c.cmView.rootView && c.cmView.rootView.view));
    if (v && v.state) return v.state.doc.toString();
  } catch (e) {}
  return c.innerText || c.textContent || '';
}
function update() {
  const t = getText();
  morse.$$('.morse-word-count').forEach(s => {
    if (t === null) { s.textContent = ''; return; }
    const n = (t.match(/\S+/g) || []).length;
    s.textContent = n + (n === 1 ? ' word' : ' words');
  });
}
