morse.watch('.sidebar-sync-button, [aria-label="Sidebar"] > div:nth-of-type(2) > button:last-child', btn => {
  if (btn.previousElementSibling?.classList.contains('morse-pomo')) return;
  const W = 25 * 60, B = 5 * 60;
  let left = W, run = false, brk = false;
  const t = morse.el('span', { class: 't' });
  const go = morse.el('button', { 'aria-label': 'Start or pause pomodoro', text: 'Start' });
  const rs = morse.el('button', { 'aria-label': 'Reset pomodoro', text: 'Reset' });
  const box = morse.el('div', { class: 'morse-pomo' }, t, go, rs);
  const draw = () => {
    const m = String(Math.floor(left / 60)).padStart(2, '0'), s = String(left % 60).padStart(2, '0');
    t.textContent = (brk ? 'Break ' : '') + m + ':' + s;
    go.textContent = run ? 'Pause' : 'Start';
    box.classList.toggle('work', run && !brk);
  };
  go.onclick = () => { run = !run; draw(); };
  rs.onclick = () => { run = false; brk = false; left = W; draw(); };
  morse.every(1000, () => {
    if (!run) return;
    left--;
    if (left <= 0) {
      brk = !brk; left = brk ? B : W;
      morse.toast(brk ? 'Pomodoro done. Take a break!' : 'Break over. Back to work!');
    }
    draw();
  });
  draw();
  btn.parentElement.insertBefore(box, btn);
});

