let work = true, left = 25*60, running = false, end = 0;
const fmt = s => String(Math.floor(s/60)).padStart(2,'0') + ':' + String(s%60).padStart(2,'0');
function render() {
  morse.$$('.mpomo').forEach(b => {
    b.classList.toggle('-break', !work);
    b.querySelector('.mpomo-mode').textContent = work ? 'Focus' : 'Break';
    b.querySelector('.mpomo-time').textContent = fmt(left);
    const ic = b.querySelector('.mpomo-go i');
    ic.className = 'fas ' + (running ? 'fa-pause' : 'fa-play');
    b.querySelector('.mpomo-go').setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');
  });
}
morse.every(500, () => {
  if (running) {
    left = Math.max(0, Math.round((end - Date.now())/1000));
    if (left === 0) {
      running = false;
      morse.toast(work ? 'Focus session done. Take a break!' : 'Break over. Back to work!');
      work = !work;
      left = (work ? 25 : 5) * 60;
    }
  }
  render();
});
morse.watch('div[aria-label="Sidebar"] > div:nth-of-type(2)', el => {
  const box = morse.el('div', { class: 'mpomo' },
    morse.el('span', { class: 'mpomo-mode' }),
    morse.el('span', { class: 'mpomo-time' }),
    morse.el('button', { class: 'mpomo-go', type: 'button', on: { click: () => {
      if (running) { running = false; }
      else { running = true; end = Date.now() + left*1000; }
      render();
    } } }, morse.el('i', { class: 'fas fa-play' })),
    morse.el('button', { class: 'mpomo-reset', type: 'button', 'aria-label': 'Reset timer', title: 'Reset', on: { click: () => {
      running = false; work = true; left = 25*60; render();
    } } }, morse.el('i', { class: 'fas fa-undo' }))
  );
  el.insertBefore(box, el.lastElementChild);
  render();
});

