morse.watch('#column2 > hr.line:first-of-type', hr => {
  const nav = hr.parentElement;
  if (nav.querySelector('.morse-filter')) return;
  const input = morse.el('input', {
    type: 'search',
    placeholder: 'Filter pages…',
    'aria-label': 'Filter documentation pages',
    value: morse.store.get('navFilter') || ''
  });
  const empty = morse.el('div', { class: 'morse-empty', text: 'No matching pages' });
  const box = morse.el('div', { class: 'morse-filter' }, input);
  const apply = () => {
    const q = input.value.trim().toLowerCase();
    let shown = 0;
    nav.querySelectorAll('ul li').forEach(li => {
      const ok = !q || li.textContent.toLowerCase().includes(q);
      li.classList.toggle('morse-hidden', !ok);
      if (ok) shown++;
    });
    empty.classList.toggle('show', shown === 0);
    morse.store.set('navFilter', input.value);
  };
  input.addEventListener('input', apply);
  input.addEventListener('keydown', e => {
    if (e.key === 'Escape') { input.value = ''; apply(); }
  });
  hr.after(box);
  box.after(empty);
  apply();
});

